      "ru": "Super ALC (Super Arylate-Carbon) — вариант ALC, в который вплетено больше волокна, поэтому отскок выше; соотношение арилата и карбона подобрано так, чтобы основание оставалось гибким. Viscaria Super ALC: 5,7 мм, реакция 12,1, вибрация 10,1 — против 11,8 / 10,3 у Viscaria."
