      "metaDescription": {
        "ua": "🚀 Super ZLC — у 1,8 раза більше карбону й ZL-волокна за масою, ніж у ZLC: реакція до 12,5. Моделі Butterfly, офіційні цифри, порівняння з Super ALC.",
        "ru": "🚀 Super ZLC — в 1,8 раза больше карбона и ZL-волокна по массе, чем в ZLC: реакция до 12,5. Модели Butterfly, официальные цифры, сравнение с Super ALC."
      },
      "h1": {
        "ua": "Super ZLC — що це за волокно і чим воно відрізняється від ZLC",
        "ru": "Super ZLC — что это за волокно и чем оно отличается от ZLC"
      },
      "body": {
        "ua": [
          "Super ZLC (Super ZL-Carbon) — ущільнена версія волокна ZLC в основах Butterfly: за даними виробника, карбонових і ZL-волокон у ньому за масою в 1,8 раза більше, ніж у звичайному ZL-Carbon. Щільніше плетіння розширює на лопаті зону високого відскоку й піднімає швидкість: у Fan Zhendong Super ZLC реакція 12,3 і вібрація 11,1, у Fan Zhendong ZLC — 11,7 і 10,8.",
          "Що означають ці числа. Реакція в Butterfly — базова швидкість основи, вібрація — наскільки жорстко відчувається удар. У парі основ Fan Zhendong Super ZLC додає до ZLC 0,6 реакції й 0,3 вібрації: основа стає і швидшою, і жорсткішою. У Super ALC інакше: Fan Zhendong Super ALC має 12,1 / 10,1 — майже та сама швидкість, але на цілу одиницю мʼякше відчуття.",
          "У глобальному каталозі Butterfly на 16.11.2026 чотири основи з Super ZLC для європейського хвату. Найшвидша — Mizutani Jun Super ZLC: 5,8 мм, реакція 12,5, вібрація 11,6. Fan Zhendong Super ZLC і Lin Yun-Ju Super ZLC мають однакові числа — 5,6 мм, 12,3 / 11,1. Harimoto Tomokazu Innerforce Super ZLC — перша основа, де Super ZLC лежить біля ядра (inner): 6,2 мм, лопать 158×152 мм, 12,0 / 10,5; за Butterfly, це найвища реакція серед основ з inner-конструкцією.",
          "У каталозі TTMAX є ще Zhang Jike Super ZLC (outer, 5,6 мм). На сайті Butterfly Global цієї моделі зараз немає, тому офіційних чисел реакції й вібрації для неї ми не наводимо.",
          "Кому підходить. Super ZLC дає найвищу реакцію серед волокон родини ALC/ZLC — до 12,5 — разом із жорстким відчуттям удару, тож це вибір для гравця з поставленою атакою, якому на ZLC бракує швидкості. Inner-версію Харімото Butterfly радить тим, хто хоче потужність Super ZLC і відчуття, що мʼяч «тримається» на ракетці. Якщо важливіший контроль, почніть зі звичайної ZLC або з inner-ZLC на кшталт Innerforce Layer ZLC (10,5 / 9,5)."
        ],
        "ru": [
          "Super ZLC (Super ZL-Carbon) — уплотнённая версия волокна ZLC в основаниях Butterfly: по данным производителя, карбоновых и ZL-волокон в нём по массе в 1,8 раза больше, чем в обычном ZL-Carbon. Более плотное плетение расширяет на лопасти зону высокого отскока и поднимает скорость: у Fan Zhendong Super ZLC реакция 12,3 и вибрация 11,1, у Fan Zhendong ZLC — 11,7 и 10,8.",
          "Что значат эти числа. Реакция у Butterfly — базовая скорость основания, вибрация — насколько жёстко ощущается удар. В паре оснований Fan Zhendong Super ZLC добавляет к ZLC 0,6 реакции и 0,3 вибрации: основание становится и быстрее, и жёстче. У Super ALC иначе: у Fan Zhendong Super ALC 12,1 / 10,1 — почти та же скорость, но ощущение на целую единицу мягче.",
          "В глобальном каталоге Butterfly на 16.11.2026 четыре основания с Super ZLC для европейского хвата. Самое быстрое — Mizutani Jun Super ZLC: 5,8 мм, реакция 12,5, вибрация 11,6. У Fan Zhendong Super ZLC и Lin Yun-Ju Super ZLC числа одинаковые — 5,6 мм, 12,3 / 11,1. Harimoto Tomokazu Innerforce Super ZLC — первое основание, где Super ZLC лежит у ядра (inner): 6,2 мм, лопасть 158×152 мм, 12,0 / 10,5; по данным Butterfly, это самая высокая реакция среди оснований с inner-конструкцией.",
          "В каталоге TTMAX есть ещё Zhang Jike Super ZLC (outer, 5,6 мм). На сайте Butterfly Global этой модели сейчас нет, поэтому официальных чисел реакции и вибрации для неё мы не приводим.",
          "Кому подходит. Super ZLC даёт самую высокую реакцию среди волокон семейства ALC/ZLC — до 12,5 — вместе с жёстким ощущением удара, так что это выбор для игрока с поставленной атакой, которому на ZLC не хватает скорости. Inner-версию Харимото Butterfly советует тем, кто хочет мощность Super ZLC и ощущение, что мяч «держится» на ракетке. Если важнее контроль, начните с обычной ZLC или с inner-ZLC вроде Innerforce Layer ZLC (10,5 / 9,5)."
        ]
      },
