            "ru": "У ALC.S тоньше ядро, поэтому, по данным Butterfly, основание легче и с более низкой вибрацией: 5,5 мм, реакция 10,1, вибрация 8,4 против 6,0 мм и 10,7 / 9,4 у Innerforce Layer ALC. Производитель советует ALC.S для атакующей игры с упором на вращение."
