            "ru": "Harimoto Tomokazu Innerforce Super ZLC: реакция 12,0 при вибрации 10,5 и толщине 6,2 мм. Butterfly называет это самой высокой реакцией среди оснований с inner-конструкцией. Самое медленное в линейке — Innerforce Layer ALC.S с реакцией 10,1."
