            "ru": "Да, в глобальном каталоге Butterfly у всех трёх моделей есть версия CS для китайского пера: ручка 82×23×31,5 мм, лопасть 158×150 мм, вибрация 10,7 (ALC), 11,4 (ZLC) и 9,4 (CAF). В каталоге TTMAX основания представлены с ручками для европейского хвата."
