      "h1": {
        "ua": "WTT Grand Smash — що це за турніри і скільки очок вони дають",
        "ru": "WTT Grand Smash — что это за турниры и сколько очков они дают"
      },
      "body": {
        "ua": [
          "WTT Grand Smash — найвищий рівень турнірів серії WTT, яку проводить World Table Tennis — комерційна структура, створена ITTF 2019 року. Перемога в одиночному розряді дає 2000 очок світового рейтингу — стільки ж, скільки перемога на Олімпійських іграх чи чемпіонаті світу. На Grand Smash розігрують п'ять розрядів: чоловічий і жіночий одиночні, чоловічий, жіночий і змішаний парні.",
          "За структурою WTT таких турнірів може бути до чотирьох на рік; у кожній одиночній сітці 64 учасники, турнір триває 10 днів плюс кваліфікація, а заявлений призовий фонд — до 3 млн доларів США. Першим став Singapore Smash 7–20 березня 2022 року з фондом 2 млн доларів: переможець одиночного розряду отримав 100 тисяч доларів і 2000 очок, фіналіст — 1400, півфіналісти — по 700, чвертьфіналісти — по 350, а поразка в першому колі основної сітки принесла 10 очок. На турнірах 2026 року шкала вже інша: півфіналіст отримував 900 очок, чвертьфіналіст — 580, учасник 1/8 фіналу — 380.",
          "Singapore Smash відтоді проходить щороку. У 2024 році додалися Saudi Smash і China Smash, у 2025-му — United States Smash і Europe Smash, і сезони 2025 та 2026 років мали вже по чотири Grand Smash. У 2026 році, крім сінгапурського, це United States Smash в Онтаріо, штат Каліфорнія (26 червня — 5 липня), Europe Smash у Мальме, Швеція (8–16 серпня), і China Smash у Пекіні (1–11 жовтня).",
          "Для гравців Butterfly ці турніри не раз ставали переломними. Фань Чженьдун виграв найперший Grand Smash — Singapore Smash 2022. Лінь Шидун переміг на China Smash 2024, а після трьох титулів на Singapore Smash 2025 у 19 років очолив світовий рейтинг. Чжу Юйлін виграла United States Smash 2025. Сора Мацусіма в липні 2026 року виграв United States Smash, у рейтингу від 5 жовтня вперше став першим номером світу, а потім виграв і China Smash, який завершився 11 жовтня.",
          "Нижче в піраміді WTT ідуть WTT Finals (1500 очок переможцю), WTT Champions (1000), Star Contender (600), Contender (400) і Feeder (125). Від WTT Champions Grand Smash відрізняється не лише очками: у Champions грають тільки одиночні розряди з сіткою на 32 учасники, а Grand Smash — це 64 гравці в одиночці плюс три парні розряди."
        ],
        "ru": [
          "WTT Grand Smash — высший уровень турниров серии WTT, которую проводит World Table Tennis — коммерческая структура, созданная ITTF в 2019 году. Победа в одиночном разряде даёт 2000 очков мирового рейтинга — столько же, сколько победа на Олимпийских играх или чемпионате мира. На Grand Smash разыгрывают пять разрядов: мужской и женский одиночные, мужской, женский и смешанный парные.",
          "По структуре WTT таких турниров может быть до четырёх в год; в каждой одиночной сетке 64 участника, турнир длится 10 дней плюс квалификация, а заявленный призовой фонд — до 3 млн долларов США. Первым стал Singapore Smash 7–20 марта 2022 года с фондом 2 млн долларов: победитель одиночного разряда получил 100 тысяч долларов и 2000 очков, финалист — 1400, полуфиналисты — по 700, четвертьфиналисты — по 350, а поражение в первом круге основной сетки принесло 10 очков. На турнирах 2026 года шкала уже другая: полуфиналист получал 900 очков, четвертьфиналист — 580, участник 1/8 финала — 380.",
          "Singapore Smash с тех пор проходит каждый год. В 2024 году добавились Saudi Smash и China Smash, в 2025-м — United States Smash и Europe Smash, и в сезонах 2025 и 2026 годов было уже по четыре Grand Smash. В 2026 году, кроме сингапурского, это United States Smash в Онтарио, штат Калифорния (26 июня — 5 июля), Europe Smash в Мальмё, Швеция (8–16 августа), и China Smash в Пекине (1–11 октября).",
          "Для игроков Butterfly эти турниры не раз становились переломными. Фань Чжэньдун выиграл самый первый Grand Smash — Singapore Smash 2022. Линь Шидун победил на China Smash 2024, а после трёх титулов на Singapore Smash 2025 в 19 лет возглавил мировой рейтинг. Чжу Юйлин выиграла United States Smash 2025. Сора Мацусима в июле 2026 года выиграл United States Smash, в рейтинге от 5 октября впервые стал первым номером мира, а затем выиграл и China Smash, который завершился 11 октября.",
          "Ниже в пирамиде WTT идут WTT Finals (1500 очков победителю), WTT Champions (1000), Star Contender (600), Contender (400) и Feeder (125). От WTT Champions Grand Smash отличается не только очками: в Champions играют только одиночные разряды с сеткой на 32 участника, а Grand Smash — это 64 игрока в одиночке плюс три парных разряда."
        ]
      },
