      "ru": "Губка — слой пористой резины между топшитом и основанием. Она пружинит при ударе и добавляет накладке скорости и дуги. Правило ITTF 2.4.3.2 допускает только один слой губки; её толщина и твёрдость — главные параметры при выборе накладки."
