      "ru": "Классическая накладка — гладкая накладка без технологии High Tension и без губок Spring Sponge: умеренная собственная скорость и много контроля. Типичный пример — Butterfly Sriver, выпущенная в 1967 году; по Butterfly, её отличил топшит из высокоэластичной синтетической резины."
