      "ru": "Spring Sponge — губка Butterfly, которая, по описанию производителя, работает как пружина: поглощает энергию мяча при ударе и отдаёт её как дополнительную силу удара. Первая накладка этого поколения — Tenergy 05 (2008); на Spring Sponge построена серия Tenergy."
