    "def": {
      "ua": "Spring Sponge X — губка Butterfly наступного після Spring Sponge покоління. За даними виробника, вона легше продавлюється при ударі, дає сильніший відскок і приблизно на 3% легша за Spring Sponge тієї ж твердості й товщини. Перша накладка з нею — Dignics 05 (2019).",
      "ru": "Spring Sponge X — губка Butterfly следующего после Spring Sponge поколения. По данным производителя, она легче продавливается при ударе, даёт более сильный отскок и примерно на 3% легче Spring Sponge той же твёрдости и толщины. Первая накладка с ней — Dignics 05 (2019)."
    },
