            "ru": "Водным клеем Butterfly. Производитель прямо пишет: для накладок поколений Spring Sponge и Spring Sponge X — Dignics, Tenergy, Glayzer и Rozena — используйте жидкий клей Free Chack, а не клеящий лист Chack Sheet II. Клею дают высохнуть минимум 10 минут, пока он не станет прозрачным."
