      "ru": "Лет — розыгрыш, результат которого не засчитывается, и его переигрывают (ITTF 2.5.3). Чаще всего это подача, задевшая сетку, но в остальном правильная; также лет — если подали неготовому принимающему, игроку помешало то, что от него не зависит, или игру прервал судья (ITTF 2.9)."
