      "ru": "Тайм-аут — перерыв до 1 минуты, который игрок или пара могут взять один раз за матч между розыгрышами, показав руками знак «T». В личных соревнованиях его может попросить и советник игрока, в командных — капитан (ITTF 3.4.4.2)."
