      "ru": "Перерыв между партиями — пауза до 1 минуты, на которую каждый игрок имеет право между соседними партиями матча (ITTF 3.4.4.1.1). На это время ракетку оставляют на столе, если судья не разрешил иное (ITTF 3.4.2.5), а игроки остаются в пределах 3 м от игровой площадки (ITTF 3.4.4.7)."
