      "ru": "Ракетка может быть любого размера, формы и веса, но основание должно быть плоским и жёстким. Минимум 85% его толщины — натуральная древесина, а клеевой слой с карбоном или стекловолокном — не толще 7,5% общей толщины или 0,35 мм, смотря что меньше (ITTF 2.4.1–2.4.2)."
