      "ru": "Судья (umpire) руководит матчем, помощник судьи (assistant umpire) помогает с отдельными решениями (ITTF 2.5.11–2.5.12). Каждый из них может признать подачу неправильной; при сомнении в первый раз за матч можно предупредить подающего, а дальше нечёткая подача — ошибка (ITTF 2.6.6)."
