    "def": {
      "ua": "Накат — атакувальний удар біля столу з помірним верхнім обертанням: закрита ракетка рухається вперед і трохи вгору, м'яч летить швидко й низько. На відміну від топспіну, головне в ньому — швидкість, а не обертання. Буває справа й зліва; накат справа зазвичай вивчають першим.",
      "ru": "Накат — атакующий удар у стола с умеренным верхним вращением: закрытая ракетка движется вперёд и немного вверх, мяч летит быстро и низко. В отличие от топспина, главное в нём — скорость, а не вращение. Бывает справа и слева; накат справа обычно осваивают первым."
    },
