    "def": {
      "ua": "Топспін — атакувальний удар із сильним верхнім обертанням: закрита ракетка зачіпає м'яч, рухаючись знизу вгору й уперед. Обертання змушує м'яч дугою опускатися на стіл, а після відскоку різко йти вперед. Це головний удар сучасної атаки, ним відповідають і на нижнє обертання.",
      "ru": "Топспин — атакующий удар с сильным верхним вращением: закрытая ракетка цепляет мяч, двигаясь снизу вверх и вперёд. Вращение заставляет мяч по дуге опускаться на стол, а после отскока резко уходить вперёд. Это главный удар современной атаки, им отвечают и на нижнее вращение."
    },
