    "def": {
      "ua": "Обертовий топспін (slow spinny loop) — топспін із максимальним верхнім обертанням і невисокою швидкістю: рух спрямований переважно вгору, м'яч летить високою дугою. Найчастіше його грають проти сильного нижнього обертання; на блоці суперник ризикує підняти м'яч або відправити його за стіл.",
      "ru": "Вращательный топспин (slow spinny loop) — топспин с максимальным верхним вращением и невысокой скоростью: движение направлено в основном вверх, мяч летит по высокой дуге. Чаще всего его играют против сильного нижнего вращения; на блоке соперник рискует поднять мяч или отправить его за стол."
    },
