      "ru": "Подрезка — контрольный удар у стола, которым возвращают мяч с нижним вращением: открытая ракетка движется вперёд и вниз под мячом, сохраняя или усиливая нижнее вращение. Основной ответ на короткую нижнюю подачу и подрезку соперника; бывает короткой и длинной."
