      "ru": "Флик — короткий атакующий удар над столом против короткого мяча: его бьют в верхней точке отскока или чуть раньше, движением предплечья и кисти вперёд-вверх. Им атакуют короткую подачу без вращения, с верхним или боковым вращением; против низкой короткой нижней он сложнее всего."
